<script>
import { gsap } from "gsap"
import store from '../services/store.js'

export default {
  name: "ImpactAnimation",
  data(){
    return {
      store
    }
  },
  mounted() {

    // FIXME : fetch theses values from the server
    let impactData = this.store.get('impact')
    let scoreRatio = impactData.scoreglobal/impactData.maxscoreglobal

    // Oui, ya de l'anglais mélangé à du français. FUCK IT
    // C'est hyper chiant de faire ça mais Gsap arrive pas à récupérer les IDs de vue autrement j'ai l'impression.
    // Donc tant pis, j'utilise $refs et c'est pas du tout flexible
    const {
      baleine_shown,
      requin_shown,
      bigger_fish_shown,
      fish_school_shown,
      elephant_shown,
      ours_shown,
      lion_shown,
      loup_shown,
      squirrel_shown,
      baleine_hidden,
      requin_hidden,
      bigger_fish_hidden,
      fish_school_hidden,
      elephant_hidden,
      ours_hidden,
      lion_hidden,
      loup_hidden,
      squirrel_hidden
    } = this.$refs;

    // La je fais un tableau pour itérer facilement
    const unlockables = [
      squirrel_shown,
      squirrel_hidden,
      loup_shown,
      loup_hidden,
      lion_shown,
      lion_hidden,
      ours_shown,
      ours_hidden,
      elephant_shown,
      elephant_hidden,
      fish_school_shown,
      fish_school_hidden,
      bigger_fish_shown,
      bigger_fish_hidden,
      requin_shown,
      requin_hidden,
      baleine_shown,
      baleine_hidden
    ];

    // Et la on génère une timeline (chaque anim à la suite de l'autre)
    let animationTime = 0.5 // s per step
    const timeline = gsap.timeline();

    for (var i = 0; i < unlockables.length; i += 2) {
      // En oubliant pas d'arrêter de débloquer quand le score ne suffit plus
      let unlockRatio = i / unlockables.length;
      if (unlockRatio > scoreRatio)
        break;

      // récupération des élements. Oui j'aurais pu faire un SVG plus simple... avec des états, par exemple...
      let uShown = unlockables[i]
      let uHiddn = unlockables[i+1]

      // On ajoute deux animations (fadeOut puis fadeIn) l'une à la suite de l'autre
      timeline.to(uHiddn, { opacity: 0.0, duration: animationTime })
      timeline.to(uShown, { opacity: 1.0, duration: animationTime })
    }

    // Au cas où : le code brute force débile 3000

    // timeline.to(squirrel_hidden, { opacity: 0.0, duration: animationTime })
    // timeline.to(squirrel_shown,  { opacity: 1.0, duration: animationTime })

    // timeline.to(loup_hidden, { opacity: 0.0, duration: animationTime })
    // timeline.to(loup_shown,  { opacity: 1.0, duration: animationTime })

    // timeline.to(lion_hidden, { opacity: 0.0, duration: animationTime })
    // timeline.to(lion_shown,  { opacity: 1.0, duration: animationTime })

    // timeline.to(ours_hidden, { opacity: 0.0, duration: animationTime })
    // timeline.to(ours_shown,  { opacity: 1.0, duration: animationTime })

    // timeline.to(elephant_hidden, { opacity: 0.0, duration: animationTime })
    // timeline.to(elephant_shown,  { opacity: 1.0, duration: animationTime })

    // timeline.to(fish_school_hidden, { opacity: 0.0, duration: animationTime })
    // timeline.to(fish_school_shown,  { opacity: 1.0, duration: animationTime })

    // timeline.to(bigger_fish_hidden, { opacity: 0.0, duration: animationTime })
    // timeline.to(bigger_fish_shown,  { opacity: 1.0, duration: animationTime })

    // timeline.to(requin_hidden, { opacity: 0.0, duration: animationTime })
    // timeline.to(requin_shown,  { opacity: 1.0, duration: animationTime })

    // timeline.to(baleine_hidden, { opacity: 0.0, duration: animationTime })
    // timeline.to(baleine_shown,  { opacity: 1.0, duration: animationTime })
  },
  props: {
    msg: String,
  },
};
</script>

